@pytest.mark.parametrize("orderly", [False, True], ids=["failure", "orderly"]) @pytest.mark.parametrize( "first,wake,signals,grace_timing", [ (100.0, 100.001, ["SIGTERM"], "late"), (100.1245, 100.125, ["SIGTERM"], "late"), (100.125, 100.126, ["SIGTERM", "SIGKILL"], "at_deadline"), (100.128, 100.129, ["SIGTERM", "SIGKILL"], "late"), (100.3745, 100.375, ["SIGTERM", "SIGKILL"], "late"), (100.375, None, [], "late"), (100.378, None, [], "late"), ], ) @pytest.mark.parametrize("prior_polls", [0, 1], ids=["never-polled", "previously-polled"]) def test_incremental_shutdown_exact_wakes_and_starved_caller( monkeypatch, orderly, first, wake, signals, grace_timing, prior_polls ): """Catch late wake/renewed grace; only OS calls and the clock are simulated.""" clock = [100.0] probes = [] worker = worker_capture.Worker( failure_bounds=worker_capture.FailureBounds(term_grace=0.125, kill_reap=0.25), close_bounds=worker_capture.CloseBounds(grace=0.125, kill_reap=0.25), ) owner = worker_capture._Owner(999999, float("inf"), ready=True, reap_attempts=prior_polls) worker.owner = owner if not orderly: worker.failure = "controlled failure"
def waitpid(pid, flags): assert pid == 999999 and flags == os.WNOHANG probes.append(clock[0]) return 0, 0
def forbidden_sleep(seconds): raise AssertionError("incremental shutdown slept")
monkeypatch.setattr(time, "monotonic", lambda: clock[0]) monkeypatch.setattr(time, "sleep", forbidden_sleep) monkeypatch.setattr(os, "waitpid", waitpid) monkeypatch.setattr(os, "killpg", lambda pid, sig: None) worker.begin_close() assert probes == [] and owner.signals == [] assert worker.kill_at == 100.125 assert owner.shutdown_deadline_monotonic == 100.375 clock[0] = first worker.begin_close() actual_wake = worker.advance_close() if wake is None: assert actual_wake is None else: > assert actual_wake == pytest.approx(wake, abs=1e-10, rel=0) E assert 100.1255 == 100.125 ± 1.0e-10 E E comparison failed E Obtained: 100.1255 E Expected: 100.125 ± 1.0e-10
